1	// Parses 200,000 log lines like: ts=1700000000 level=info msg="..." ms=12
2	const lines = [];
3	for (let i = 0; i < 200_000; i++) {
4	  lines.push(`ts=${1_700_000_000 + i} level=${i % 7 ? "info" : "error"} msg="request ${i} done" ms=${i % 250}`);
5	}
6	const input = lines.join("\n");
7	
8	export function parse(text) {
9	  const records = [];
10	  for (const line of text.split("\n")) {
11	    const record = {};
12	    for (const field of line.match(/\w+=("[^"]*"|\S+)/g) ?? []) {
13	      const [key, ...rest] = field.split("=");
14	      let value = rest.join("=");
15	      if (value.startsWith('"')) value = value.slice(1, -1);
16	      record[key] = /^\d+$/.test(value) ? Number(value) : value;
17	    }
18	    records.push(JSON.parse(JSON.stringify(record)));
19	  }
20	  return records;
21	}
22	
23	const start = performance.now();
24	const records = parse(input);
25	const errors = records.filter((r) => r.level === "error").length;
26	console.log(`${records.length} lines, ${errors} errors, ${(performance.now() - start).toFixed(0)} ms`);
